joi_block.script:
hold_ticks := 0
if ((#Bedroom #TemperatureSensor).temperatureSensor_temperature > 28) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 300) {
(#Plug).switch_on()
        delay(20 MIN)
(#Plug).switch_off()
        break
}
}
else {
hold_ticks = 0
}

